SELECT COUNT(*) n, COUNT(DISTINCT web_order_id) d, SUM(CASE WHEN status NOT IN ('delivered','collected') THEN 1 ELSE 0 END) other_status
FROM fact_web_order
WHERE CAST(timezone('Europe/Helsinki', dispatch_ts_utc AT TIME ZONE 'UTC') AS DATE) BETWEEN DATE '2025-12-15' AND DATE '2025-12-23';
